"""Python generator for ml-hpi (IDL -> typing.Protocol classes)."""
from __future__ import annotations
from collections import defaultdict
from io import StringIO
from pathlib import Path
from typing import Union

from ml_hpi.model import Interface, Method, MlHpiDoc
from .gen_base import Generator


# Annotated-style type aliases emitted at the top of generated files
_ANNOTATED_ALIASES = """\
Int8 = Annotated[int, "int8"]
UInt8 = Annotated[int, "uint8"]
Int16 = Annotated[int, "int16"]
UInt16 = Annotated[int, "uint16"]
Int32 = Annotated[int, "int32"]
UInt32 = Annotated[int, "uint32"]
Int64 = Annotated[int, "int64"]
UInt64 = Annotated[int, "uint64"]
Addr = Annotated[int, "addr"]
Addr32 = Annotated[int, "addr32"]
Addr64 = Annotated[int, "addr64"]
UIntPtr = Annotated[int, "uintptr"]
"""


class GenPython(Generator):
    """Generates a ``.py`` file per package containing ``typing.Protocol``
    classes.

    *style* controls type annotations:

    - ``"plain"``: bare ``int`` / ``bool`` / ``None``.
    - ``"annotated"``: ``Annotated[int, "uint32"]`` aliases.
    - ``"ctypes"``: ``ctypes.c_uint32`` etc.
    """

    def __init__(self, doc: MlHpiDoc, style: str = "plain", addr_bits: int = 64):
        super().__init__(doc)
        if style not in ("plain", "annotated", "ctypes"):
            raise ValueError(f"Unknown style {style!r}")
        self.style = style
        self.addr_bits = addr_bits

    def generate(self, outdir: Union[str, Path]) -> list[Path]:
        outdir = Path(outdir)
        outdir.mkdir(parents=True, exist_ok=True)

        pkgs: dict[str, list[Interface]] = defaultdict(list)
        for iface in self.doc.spec.interfaces:
            pkgs[iface.pkg()].append(iface)

        generated: list[Path] = []
        for pkg_name, ifaces in pkgs.items():
            out = StringIO()
            out.write(f'# Auto-generated by ml-hpi GenPython -- do not edit\n')
            self._write_imports(out)
            out.write("\n")
            for iface in ifaces:
                self._write_protocol(out, iface)
                out.write("\n")

            fname = f"{pkg_name}.py"
            outfile = outdir / fname
            outfile.write_text(out.getvalue())
            generated.append(outfile)

        return generated

    def _write_imports(self, out: StringIO) -> None:
        out.write("from __future__ import annotations\n")
        out.write("import typing\n")
        if self.style == "annotated":
            out.write("from typing import Annotated\n")
            out.write("\n")
            out.write(_ANNOTATED_ALIASES)
        elif self.style == "ctypes":
            out.write("import ctypes\n")

    def _write_protocol(self, out: StringIO, iface: Interface) -> None:
        short = iface.short_name()
        if iface.extends:
            base_short = iface.extends.rsplit(".", 1)[-1]
            out.write(f"\nclass {short}({base_short}, typing.Protocol):\n")
        else:
            out.write(f"\nclass {short}(typing.Protocol):\n")

        has_body = False

        for meth in iface.methods:
            self._write_method(out, meth)
            has_body = True

        for mem in iface.members:
            self._write_member(out, mem)
            has_body = True

        if not has_body:
            out.write("    ...\n")

    def _write_method(self, out: StringIO, meth: Method) -> None:
        rtype = self._map_type(meth.rtype)
        params = ", ".join(
            f"{p.name}: {self._map_type(p.type)}" for p in meth.params
        )
        self_params = f"self, {params}" if params else "self"

        if meth.is_blocking():
            ll = meth.get_log_level()
            pragma = f"  # ml-hpi: log_level={ll}" if ll else ""
            out.write(f"    async def {meth.name}({self_params}) -> {rtype}: ...{pragma}\n")
        else:
            ll = meth.get_log_level()
            pragma = f"  # ml-hpi: log_level={ll}" if ll else ""
            out.write(f"    def {meth.name}({self_params}) -> {rtype}: ...{pragma}\n")

    def _write_member(self, out: StringIO, mem) -> None:
        mem_type = mem.type.rsplit(".", 1)[-1]
        if mem.kind == "array":
            out.write(f"    def {mem.name}_at(self, idx: int) -> {mem_type}: ...\n")
            out.write(f"    def {mem.name}_size(self) -> int: ...\n")
        else:
            out.write(f"    def {mem.name}(self) -> {mem_type}: ...\n")

    def _map_type(self, ml_type: str) -> str:
        return self.python_type(ml_type, self.style, self.addr_bits)
